import json
got=json.load(open('/tmp/f_5209.got')); want=json.load(open('/tmp/f_5209.want'))
def walk(a,b,path=''):
    if type(a)!=type(b):
        print('TYPE',path,a,b); return
    if isinstance(a,dict):
        for k in set(a)|set(b):
            if k not in a or k not in b: print('KEY',path,k); continue
            walk(a[k],b[k],path+'.'+k)
    elif isinstance(a,list):
        if len(a)!=len(b): print('LEN',path,len(a),len(b)); return
        for i,(x,y) in enumerate(zip(a,b)): walk(x,y,path+'[%d]'%i)
    else:
        if a!=b: print('VAL',path,a,b)
walk(got,want)
